101			if err != nil {
102				success = 0
103				payload = err.Error()
104			}
105			C.callInvokeResultCallback(
106				callback,
107				C.uint64_t(requestID),
108				success,
109				C.CString(payload),
110			)
111		}
112		nativebridge.InvokeAsync(
113			C.GoString(method),
114			C.GoString(path),
115			C.GoString(query),
116			C.GoString(body),
117			complete,
118		)
119	}
120	
121	//export SubscribeTaskEvents
122	func SubscribeTaskEvents(mask C.ulonglong, callback C.uintptr_t) {
123		if mask == 0 || callback == 0 {
124			rest.SubscribeTaskEvents(0, nil)
125			return
126		}
127		rest.SubscribeTaskEvents(uint64(mask), func(payload string) {
128			// Ownership crosses the asynchronous Dart callback boundary. Dart frees
129			// this string with FreeCString after decoding it.
130			C.callTaskEventCallback(callback, C.CString(payload))
131		})
132	}
133	
134	//export FreeCString
135	func FreeCString(value *C.char) {
136		if value != nil {
137			C.free(unsafe.Pointer(value))
138		}
139	}
